t-sm font-semibold"><span>Nama PIC <span class="text-danger">*</span></span><input name="account_name" required placeholder="Nama penanggung jawab" autocomplete="name" class="h-11 rounded-lg border border-line bg-white px-3 font-normal"></label><label class="grid gap-2 text-sm font-semibold"><span>Username <span class="text-danger">*</span></span><input name="login_username" required placeholder="Contoh: pic.client" autocomplete="username" class="h-11 rounded-lg border border-line bg-white px-3 font-normal"></label><label class="grid gap-2 text-sm font-semibold"><span>Email login <span class="text-danger">*</span></span><input type="email" name="login_email" required placeholder="pic@perusahaan.com" autocomplete="email" class="h-11 rounded-lg border border-line bg-white px-3 font-normal"></label><label class="grid gap-2 text-sm font-semibold"><span>Password <span class="text-danger">*</span></span><div class="relative"><input type="password" name="password" data-required-on-create autocomplete="new-password" placeholder="Minimal 8 karakter" class="h-11 w-full rounded-lg border border-line bg-white px-3 pr-12 font-normal"><button type="button" data-password-toggle class="absolute right-1.5 top-1/2 grid size-9 -translate-y-1/2 place-items-center rounded-lg text-slate-400 hover:bg-slate-100 hover:text-slate-700" aria-label="Tampilkan password"><span data-password-show><x-icon name="eye" /></span><span data-password-hide class="hidden"><x-icon name="eye-slash" /></span></button></div></label><label class="grid gap-2 text-sm font-semibold"><span>Konfirmasi password <span class="text-danger">*</span></span><div class="relative"><input type="password" name="password_confirmation" data-required-on-create autocomplete="new-password" placeholder="Ulangi password" class="h-11 w-full rounded-lg border border-line bg-white px-3 pr-12 font-normal"><button type="button" data-password-toggle class="absolute right-1.5 top-1/2 grid size-9 -translate-y-1/2 place-items-center rounded-lg text-slate-400 hover:bg-slate-100 hover:text-slate-700" aria-label="Tampilkan konfirmasi password"><span data-password-show><x-icon name="eye" /></span><span data-password-hide class="hidden"><x-icon name="eye-slash" /></span></button></div></label></div></section><div class="flex justify-end gap-3"><button type="button" data-client-close class="rounded-lg border border-line px-4 py-2.5 text-sm font-semibold">Batal</button><button class="rounded-lg bg-primary-600 px-4 py-2.5 text-sm font-semibold text-white">Simpan</button></div></form></div></div>
